        let hash = self.hash(&**key);
        self.inner.get_key_value_and_then(&**key, hash, |k, entry| {
            let i = &self.inner;
            let (ttl, tti, va) = (&i.time_to_live(), &i.time_to_idle(), &i.valid_after());
